INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (326361, 14266, 'The Guardian', 'en', 'Romania shuts its last nuclear reactor as drought-hit Danube river drops to record low', 'https://www.theguardian.com/world/2026/aug/14/romania-nuclear-plant-shut-down-cernavoda-danube-river-water-drought', 'Cernavoda shutdown poses immediate problems for Moldova, which relies on Romanian power ​to cover its own electricity shortages Romania has been forced to shut down the last working ⁠reactor at its only nuclear plant after drought caused the Danube river to fall to record lows – a rare move that will immediately affect power supplies in neighbouring Moldova. Drought and record-low water levels have deepened fears of an energy crisis across Europe , which is facing a new summer heatwave. Continue reading...', 'https://i.guim.co.uk/img/media/c0fba84aed96589748e2eb1cd62764c1fb758e7d/1139_0_6880_5504/master/6880.jpg?width=140&quality=85&auto=format&fit=max&s=8d4812cc49fb9e76d92ef803efe0b428', '2026-08-14T01:20:26+00:00', '2026-08-14T01:56:48.291471'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
