INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (332285, 14334, 'South China Morning Post', 'en', 'Why Prabowo’s softened tone might not signal a change in Indonesia’s economic course', 'https://www.scmp.com/news/asia/southeast-asia/article/3363986/indonesias-prabowo-defends-record-touts-food-self-sufficiency-independence-day-speech', 'Indonesian President Prabowo Subianto acknowledged on Friday that his government had yet to fulfil all its promises, an unusual note of self-criticism as he sought to reassure Indonesians and investors while pressing ahead with his ambitious economic agenda. Analysts said the shift in tone was notable but saw little evidence that Prabowo was changing course on his more state-directed economic policies. In his annual state address ahead of Independence Day and a later budget speech, Prabowo said...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/65592ce6-a41b-47c3-8bfa-3f36159a3b65_9e65f8b9.jpg?itok=ewCdKHzI&v=1786680849', '2026-08-14T04:14:18+00:00', '2026-08-14T15:03:28.907312'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
