INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333010, 14334, 'The Times of India', 'en', 'President Murmu approves 78 gallantry awards', 'https://timesofindia.indiatimes.com/india/president-murmu-approves-78-gallantry-awards/articleshow/133246351.cms', 'President Droupadi Murmu has approved a total of seventy-eight gallantry awards, including nine Kirti Chakras and nineteen Shaurya Chakras, recognizing the exceptional bravery of defence personnel and central armed police forces. Many of these awards are awarded posthumously. This recognition underscores the remarkable commitment and courage displayed by individuals across the Army, Navy, and Air Force, emphasizing the nation''s deep respect and appreciation for their service.', 'https://static.toiimg.com/photo/msid-133246604,imgsize-157464.cms', '2026-08-14T16:01:51+00:00', '2026-08-14T17:12:44.387769'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
