INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (320887, 14345, 'BBC News', 'en', 'Engine parts smashed Ryanair window that man''s head was sucked out of, report says', 'https://www.bbc.co.uk/news/articles/cr59j4z3vl8o', 'A preliminary report by US investigators says an engine fan blade broke on last month''s flight from Greece to Germany.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/1623/live/fc15b5f0-975d-11f1-9240-c70a29f1c818.jpg', '2026-08-13T21:43:47+00:00', '2026-08-13T22:50:29.082287'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (323975, 14345, 'South China Morning Post', 'en', 'Bird remains found in engine after man nearly sucked out of window on Ryanair flight', 'https://www.scmp.com/news/world/europe/article/3363961/bird-remains-found-engine-after-man-nearly-sucked-out-window-ryanair-flight', '⁠Bird remains were found ⁠in the engine of a Ryanair Boeing 737 NG plane where a passenger was partially sucked through a broken window shortly after take-off from Greece in July, the US National Transportation Safety Board said on Thursday. The NTSB ‌is investigating the incident where a piece of the engine broke off the plane and smashed the window. The plane, headed to Germany, lost pressure and was forced to make an emergency landing. The NTSB said in its preliminary report into the July 10...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/4cfbb2a7-4f6b-4a57-96d3-114149325319_d90ca43d.jpg?itok=SZHqqma6&v=1786653026', '2026-08-13T20:30:30+00:00', '2026-08-13T22:55:10.682965'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
