INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329391, 14345, 'The Guardian', 'en', 'Ryanair window that passenger was partly sucked out of was broken by engine debris, report finds', 'https://www.theguardian.com/business/2026/aug/14/ryanair-engine-parts-shattered-window-passenger-partly-sucked-out-of-report', 'Fan blade broke off shortly after takeoff on 10 July flight from Greece to Germany, preliminary findings show Business live – latest updates Broken engine parts were responsible for shattering a window on a Ryanair plane, causing a passenger to be partly sucked out mid-flight in July, US investigators have said. A preliminary report by the National Transportation Safety Board (NTSB) found an engine fan blade broke off shortly after takeoff on the 10 July flight from Greece to Germany shattering the window and damaging the fuselage. Continue reading...', 'https://i.guim.co.uk/img/media/a517b301e2ddfc58282138c82822c41b6635aedc/45_320_2917_2333/master/2917.jpg?width=140&quality=85&auto=format&fit=max&s=267e7408619193f694857cb6501dd468', '2026-08-14T10:28:10+00:00', '2026-08-14T14:58:19.689830'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
